/**
 * FOTOS REAIS das placas de advertência de geração própria — enviadas pelo
 * usuário (jul/2026) para irem NATIVAS no diagrama (não como redesenho
 * vetorial). Comprimidas para ~360px/JPEG q72 antes de virar data URL.
 * Entram na cena como `PlacedPhoto` (camada PHOTO) — aparecem no canvas,
 * no SVG e no PDF; o DXF não carrega raster (limitação do formato R12).
 * `w`/`h` em mm preservam a proporção original de cada foto.
 */
export interface WarningPlateImage { href: string; w: number; h: number }

/** Placa amarela "CUIDADO / RISCO DE CHOQUE ELÉTRICO / GERAÇÃO PRÓPRIA" — CPFL e demais concessionárias. */
export const WARNING_PLATE_GENERIC: WarningPlateImage = {
  w: 24, h: 17.2,
  href: 'data:image/jpeg;base64,',
};

/** Placa da ENEL "AVISO / RISCO DE CHOQUE ELÉTRICO / RETORNO GERADOR DE ENERGIA". */
export const WARNING_PLATE_ENEL: WarningPlateImage = {
  w: 19, h: 18.7,
  href: 'data:image/jpeg;base64,',
};
